    title: "Surds: operations & rationalisation", env: "paper", values: { mode: "rat", k: 2, b: 5, cc: 3, sg: "+", p: 3, q: 2, r: 4, s: 1, n: 2 },
    controls: [{ type: "tabs", key: "mode", label: "Mode", options: [["rat", "Rationalise k/(√b ± √c)"], ["mul", "(p + q√n)(r + s√n)"], ["div", "(p + q√n)/(r + s√n)"]] }, { key: "k", label: "k", min: 1, max: 12, show: W("mode", "rat") }, { key: "b", label: "b", min: 2, max: 20, show: W("mode", "rat") }, { key: "cc", label: "c", min: 1, max: 20, show: W("mode", "rat") }, { type: "select", key: "sg", label: "Sign", options: [["+", "+"], ["-", "−"]], show: W("mode", "rat") },
      { key: "p", label: "p", min: -6, max: 9, show: W("mode", "mul", "div") }, { key: "q", label: "q", min: -6, max: 6, show: W("mode", "mul", "div") }, { key: "r", label: "r", min: -6, max: 9, show: W("mode", "mul", "div") }, { key: "s", label: "s", min: -6, max: 6, show: W("mode", "mul", "div") }, { key: "n", label: "n (surd)", min: 2, max: 15, show: W("mode", "mul", "div") }],
