    table(s, c) { if (c.mode !== "expand") return ""; const T2 = this.terms(c); return T(["r", "ⁿCᵣ", "a^(n−r)", "b^r", "coefficient of xʳ"], T2.map((t) => [t.r, t.C, f(Math.pow(c.a, c.n - t.r)), f(Math.pow(c.b, t.r)), f(t.coef)])); },
