    draw(g, s, c, B) { const P = B.P;
      if (c.mode === "between") { const F = MK.tryParse(c.f1).fn, G = MK.tryParse(c.f2).fn; if (!F || !G) return; const xs = MK.roots((x) => F(x) - G(x), -6, 6); const m = B.axes({ xmin: -5, xmax: 5, ymin: -6, ymax: 8 }); if (xs.length >= 2) { const lo = xs[0], hi = xs[xs.length - 1]; B.shade(m, (x) => Math.max(F(x), G(x)), lo, hi, MK.isNight() ? "rgba(91,214,140,.25)" : "rgba(21,128,61,.22)", (x) => Math.min(F(x), G(x))); xs.forEach((x) => B.dot(m.X(x), m.Y(F(x)), P.red, 5, "x = " + f(x, 3), { dy: -10 })); } B.plot(m, F, P.blue, 2.6); B.plot(m, G, P.amber, 2.6); return; }
      const F = MK.tryParse(c.fn).fn; if (!F) return; const a = Math.min(c.a, c.b), b = Math.max(c.a, c.b), ys = []; for (let x = a - 1; x <= b + 1; x += 0.1) ys.push(F(x)); const m = B.axes({ xmin: a - 1, xmax: b + 1, ymin: Math.min(0, ...ys) - 1, ymax: Math.max(1, ...ys) + 1 }), h = (b - a) / c.n;
      for (let i = 0; i < c.n; i++) { const x0 = a + i * h; B.poly([[m.X(x0), m.Y(0)], [m.X(x0), m.Y(F(x0))], [m.X(x0 + h), m.Y(F(x0 + h))], [m.X(x0 + h), m.Y(0)]], P.blue, P.fillB, 1.2); } B.plot(m, F, P.ink, 2.6); },
    hud(s, c) { if (c.mode === "between") { const F = MK.tryParse(c.f1).fn, G = MK.tryParse(c.f2).fn; if (!F || !G) return [{ title: "Area", lines: ["check the expressions"] }]; const xs = MK.roots((x) => F(x) - G(x), -6, 6); if (xs.length < 2) return [{ title: "Area", lines: ["the curves must meet twice"] }]; const A = Math.abs(MK.integrate((x) => F(x) - G(x), xs[0], xs[xs.length - 1])); return [{ title: "Area between curves", lines: ["A = ∫ (upper − lower) dx", `limits: where f = g → ${xs.map((x) => f(x, 3)).join(", ")}`, [`A = ${f(A, 4)} square units`, null, true]] }]; }
      const F = MK.tryParse(c.fn).fn; if (!F) return []; const a = Math.min(c.a, c.b), b = Math.max(c.a, c.b), h = (b - a) / c.n; let sum = F(a) + F(b); for (let i = 1; i < c.n; i++) sum += 2 * F(a + i * h); const T2 = h / 2 * sum, ex = MK.integrate(F, a, b);
      return [{ title: "Trapezium rule", lines: ["A ≈ h/2 [y₀ + 2(y₁ + … + yₙ₋₁) + yₙ]", `h = (b − a)/n = ${f(h, 4)}`, [`A ≈ ${f(T2, 5)}`, null, true], `exact ${f(ex, 5)}, error ${f(Math.abs(T2 - ex), 5)}`] }]; },
    readouts(s, c) { if (c.mode === "trap") { const F = MK.tryParse(c.fn).fn; if (!F) return []; return [["Exact", f(MK.integrate(F, Math.min(c.a, c.b), Math.max(c.a, c.b)), 5)]]; } return [["Mode", "area between curves"]]; },
